WITH RECURSIVE bom_tree (bom_id, parent_material_code, revision, line_no, component_material_code, quantity, uom, level_no, path) AS (SELECT h.bom_id, h.parent_material_code, h.revision, l.line_no, l.component_material_code, CAST(l.quantity AS NUMERIC(12,3)), l.uom, 1, CONCAT(h.parent_material_code, '>', l.component_material_code) FROM mes_bom_header h JOIN mes_bom_line l ON l.bom_id = h.bom_id WHERE h.parent_material_code = ? AND h.status = 'active' UNION ALL SELECT h2.bom_id, h2.parent_material_code, h2.revision, l2.line_no, l2.component_material_code, CAST(bt.quantity * l2.quantity AS NUMERIC(12,3)), l2.uom, bt.level_no + 1, CONCAT(bt.path, '>', l2.component_material_code) FROM bom_tree bt JOIN mes_bom_header h2 ON h2.parent_material_code = bt.component_material_code AND h2.status = 'active' JOIN mes_bom_line l2 ON l2.bom_id = h2.bom_id) SELECT bt.bom_id, bt.parent_material_code, bt.revision, bt.line_no, bt.component_material_code, COALESCE(m.display_name, '') AS component_name, bt.quantity, bt.uom, bt.level_no, bt.path FROM bom_tree bt LEFT JOIN mes_genealogy_material m ON m.material_code = bt.component_material_code ORDER BY bt.level_no, bt.line_no, bt.component_material_code
